for (const museum of Object.values(museumData)) {
  for (const work of museum.works) {
    const significance = workSignificance[museum.id]?.[work.id];
    if (!significance && !work.significance) throw new Error(`${museum.id}/${work.id} 缺少显式重要性分级`);
    if (significance) {
      work.significance = significance[0];
      work.preciousWhy = significance[1];
    }
  }
}
